// An options object whose timeZone is a getter that answers another zone
// each time it is read, one that counts, and a proxy that counts its reads.
var reads = 0;
var format = new Intl.DateTimeFormat("en-US", {
  get timeZone() {
    reads++;
    return reads === 1 ? "Asia/Tokyo" : "UTC";
  },
});
var timeReads = 0;
var time = new Date(0).toLocaleTimeString("en-US", {
  get timeZone() {
    timeReads++;
    return timeReads === 1 ? "Asia/Tokyo" : "UTC";
  },
});
var gets = 0;
var proxied = new Intl.DateTimeFormat(
  "en-US",
  new Proxy(
    { timeZone: "America/New_York" },
    {
      get: function (target, key) {
        if (key === "timeZone") gets++;
        return target[key];
      },
    },
  ),
);
module.exports = {
  zone: format.resolvedOptions().timeZone,
  reads: reads,
  time: time,
  timeReads: timeReads,
  proxied: proxied.resolvedOptions().timeZone,
  gets: gets,
};
